def _get_multidict_value(
    field: ModelField, values: Mapping[str, Any], alias: str | None = None
) -> Any:
    alias = alias or get_validation_alias(field)
    if alias is None:
        return None

    field_info = getattr(field, "field_info", None)
    if (
        isinstance(field_info, params.Header)
        and getattr(field_info, "convert_underscores", True)
        and "_" in alias
    ):
        return None

    if alias in values:
        return values[alias]
    return None

